sys_script_client.script:
function onLoad() {

	g_form.setVisible('current_game', false);

    var ajax = new GlideAjax('x_842748_tes_lore.tesUtils');
    ajax.addParam('sysparm_name', 'getQuestions');
    ajax.addParam('sysparm_qid', g_form.getUniqueValue());
    ajax.getXMLAnswer(function(answer) {
        var questions = JSON.parse(answer);

        questions.forEach(function(question) {
            if (question.game == g_form.getValue('current_game')) {
                g_form.setDisplay('variables.' + question.name, true);
            } else {
                g_form.setDisplay('variables.' + question.name, false);
            }
        });
    });
}
